const config = {
  "previewFeatures": [
    "postgresqlExtensions"
  ],
  "clientVersion": "7.3.0",
  "engineVersion": "9d6ad21cbbceab97458517b147a6a09ff43aa735",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../generated/prisma-client\"\n  previewFeatures = [\"postgresqlExtensions\"]\n  binaryTargets   = [\"native\", \"debian-openssl-1.1.x\", \"debian-openssl-3.0.x\", \"linux-musl-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider   = \"postgresql\"\n  extensions = [uuid_ossp(map: \"uuid-ossp\")]\n}\n\n// ============================================================================\n// User System - 用户系统\n// ============================================================================\nenum SexType {\n  UNKNOWN\n  MALE\n  FEMALE\n\n  @@map(\"sex_type\")\n}\n\nmodel UserInfo {\n  id           String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  nickname     String  @default(\"\") @db.VarChar(255)\n  code         String? @unique @db.VarChar(255)\n  avatarFileId String? @map(\"avatar_file_id\") @db.Uuid\n  sex          SexType @default(UNKNOWN)\n  locale       String? @db.VarChar(20)\n  isAnonymity  Boolean @default(false) @map(\"is_anonymity\")\n  isAdmin      Boolean @default(false) @map(\"is_admin\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // Account Identifiers (登录标识)\n  deviceId      String? @unique @map(\"device_id\") @db.VarChar(255)\n  wechatOpenid  String? @unique @map(\"wechat_openid\") @db.VarChar(255)\n  wechatUnionId String? @unique @map(\"wechat_union_id\") @db.VarChar(255)\n  googleSub     String? @unique @map(\"google_sub\") @db.VarChar(255)\n  discordId     String? @unique @map(\"discord_id\") @db.VarChar(255)\n  mobile        String? @unique @map(\"mobile\") @db.VarChar(40)\n  email         String? @unique @map(\"email\") @db.VarChar(255)\n\n  // Relations\n  avatarFile       FileSource?        @relation(fields: [avatarFileId], references: [id], onDelete: SetNull)\n  wechatAuth       WechatAuth?\n  googleAuth       GoogleAuth?\n  discordAuth      DiscordAuth?\n  mobileAuth       MobileAuth?\n  emailAuth        EmailAuth?\n  sentMessages     Message[]          @relation(\"SentMessages\")\n  receivedMessages MessageRecipient[] @relation(\"ReceivedMessages\")\n  bots             Bot[]\n  providerKeys     ProviderKey[]\n  personaTemplates PersonaTemplate[]\n  operateLogs      OperateLog[]\n\n  @@index([code])\n  @@index([isDeleted, isAdmin])\n  @@index([createdAt(sort: Desc)])\n  @@index([nickname])\n  @@index([avatarFileId])\n  @@index([deviceId])\n  @@index([wechatOpenid])\n  @@index([googleSub])\n  @@index([discordId])\n  @@index([mobile])\n  @@index([email])\n  @@map(\"u_user_info\")\n}\n\n// ============================================================================\n// Persona Template System - 人格模板系统（须在 UserInfo 后、被引用前定义）\n// ============================================================================\n\n/// PersonaTemplate - 人格模板\n/// 支持系统预设模板和用户自定义模板\n/// 图标支持两种形式（二选一）：\n/// - emoji: emoji 字符串（如 \"🤖\"）\n/// - avatarFileId: 上传的头像文件 ID（关联 FileSource）\nmodel PersonaTemplate {\n  id           String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name         String  @db.VarChar(255)\n  emoji        String? @db.VarChar(10)\n  avatarFileId String? @map(\"avatar_file_id\") @db.Uuid\n  tagline      String  @db.VarChar(500)\n  soulMarkdown String  @map(\"soul_markdown\") @db.Text\n  soulPreview  String? @map(\"soul_preview\") @db.VarChar(500)\n  isSystem     Boolean @default(false) @map(\"is_system\")\n  locale       String  @default(\"en\") @db.VarChar(10) // en, zh-CN\n  createdById  String? @map(\"created_by_id\") @db.Uuid\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  createdBy  UserInfo?   @relation(fields: [createdById], references: [id], onDelete: SetNull)\n  avatarFile FileSource? @relation(fields: [avatarFileId], references: [id], onDelete: SetNull)\n  bots       Bot[]\n\n  @@index([isSystem])\n  @@index([createdById])\n  @@index([avatarFileId])\n  @@index([isDeleted])\n  @@index([locale])\n  @@index([createdAt(sort: Desc)])\n  @@map(\"b_persona_template\")\n}\n\n// ============================================================================\n// Auth Tables - 认证信息表（只存 token/password，不存 userId）\n// ============================================================================\n\nmodel WechatAuth {\n  openid       String    @unique @db.VarChar(255)\n  sessionKey   String?   @map(\"session_key\") @db.Text\n  refreshToken String?   @map(\"refresh_token\") @db.Text\n  isDeleted    Boolean   @default(false) @map(\"is_deleted\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt    DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [openid], references: [wechatOpenid], onDelete: Cascade)\n\n  @@index([openid])\n  @@map(\"u_wechat_auth\")\n}\n\nmodel GoogleAuth {\n  sub           String    @unique @db.VarChar(255)\n  email         String    @db.VarChar(255)\n  verifiedEmail Boolean   @default(true) @map(\"verified_email\")\n  atHash        String?   @map(\"at_hash\") @db.VarChar(255)\n  name          String?   @db.VarChar(255)\n  picture       String?   @db.Text\n  givenName     String?   @map(\"given_name\") @db.VarChar(255)\n  familyName    String?   @map(\"family_name\") @db.VarChar(255)\n  exp           Int\n  iat           Int\n  isDeleted     Boolean   @default(false) @map(\"is_deleted\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt     DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [sub], references: [googleSub], onDelete: Cascade)\n\n  @@index([sub])\n  @@index([email])\n  @@map(\"u_google_auth\")\n}\n\nmodel DiscordAuth {\n  discordId     String    @unique @map(\"discord_id\") @db.VarChar(255)\n  email         String    @db.VarChar(255)\n  verifiedEmail Boolean   @default(true) @map(\"verified_email\")\n  name          String?   @db.VarChar(255)\n  accessToken   String?   @map(\"access_token\") @db.Text\n  refreshToken  String?   @map(\"refresh_token\") @db.Text\n  isDeleted     Boolean   @default(false) @map(\"is_deleted\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt     DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [discordId], references: [discordId], onDelete: Cascade)\n\n  @@index([discordId])\n  @@index([email])\n  @@map(\"u_discord_auth\")\n}\n\nmodel MobileAuth {\n  mobile    String    @unique @db.VarChar(40)\n  password  String    @db.VarChar(255)\n  verified  Boolean   @default(false)\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [mobile], references: [mobile], onDelete: Cascade)\n\n  @@index([mobile])\n  @@map(\"u_mobile_auth\")\n}\n\nmodel EmailAuth {\n  email     String    @unique @db.VarChar(255)\n  password  String    @db.VarChar(255)\n  verified  Boolean   @default(false)\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [email], references: [email], onDelete: Cascade)\n\n  @@index([email])\n  @@map(\"u_email_auth\")\n}\n\n// ============================================================================\n// Risk Detection - 风险检测记录\n// ============================================================================\n\nmodel RiskDetectionRecord {\n  id        String    @id @db.VarChar(255)\n  action    String    @db.VarChar(100)\n  data      Json?\n  status    Int       @default(0)\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  @@index([action])\n  @@index([status])\n  @@index([createdAt(sort: Desc)])\n  @@map(\"risk_detection_record\")\n}\n\n// ============================================================================\n// System Task Queue - 系统任务队列（短信/邮件发送历史）\n// RabbitMQ + BullMQ（队列调度层）\n// SystemTaskQueue 只在任务最终完成（成功/失败）后写入，用于审计、统计、用户查询发送历史\n// 不参与队列调度和重试逻辑\n// ============================================================================\n\nenum TaskType {\n  SMS\n  EMAIL\n  PUSH\n\n  @@map(\"task_type\")\n}\n\nenum TaskStatus {\n  SUCCESS\n  FAILED\n\n  @@map(\"task_status\")\n}\n\nmodel SystemTaskQueue {\n  id           String     @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  taskType     TaskType   @map(\"task_type\")\n  status       TaskStatus\n  recipient    String     @db.VarChar(255)\n  templateCode String?    @map(\"template_code\") @db.VarChar(100)\n  templateData Json?      @map(\"template_data\")\n  content      String?    @db.Text\n  subject      String?    @db.VarChar(500)\n  retryCount   Int        @default(0) @map(\"retry_count\")\n  processedAt  DateTime   @map(\"processed_at\") @db.Timestamptz(6)\n  errorMessage String?    @map(\"error_message\") @db.Text\n  metadata     Json?\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([taskType, status])\n  @@index([recipient, createdAt(sort: Desc)])\n  @@index([createdAt(sort: Desc)])\n  @@map(\"system_task_queue\")\n}\n\nenum FileBucketVendor {\n  oss\n  us3\n  qiniu\n  s3\n  gcs\n  tos\n  tencent\n  ksyun\n\n  @@map(\"file_bucket_vendor\")\n}\n\nenum FileEnvType {\n  dev\n  test\n  prod\n  produs\n  prodap\n\n  @@map(\"file_env_type\")\n}\n\nmodel FileSource {\n  id                        String           @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  isUploaded                Boolean          @default(false) @map(\"is_uploaded\")\n  bucket                    String           @db.VarChar(255)\n  key                       String           @unique @db.VarChar(255)\n  hash                      String?          @db.VarChar(255)\n  thumbImg                  String?          @map(\"thumb_img\") @db.VarChar(255)\n  fsize                     Float            @default(0)\n  mimeType                  String           @default(\"\") @map(\"mime_type\") @db.VarChar(255)\n  type                      Int              @default(0)\n  endUser                   String?          @map(\"end_user\") @db.VarChar(255)\n  status                    Int              @default(0)\n  sha256                    String?          @db.VarChar(255)\n  parts                     Int[]\n  ext                       String           @default(\"\") @db.VarChar(255)\n  expireAt                  DateTime?        @map(\"expire_at\") @db.Timestamptz(6)\n  transitionToIaAt          DateTime?        @map(\"transition_to_ia_at\") @db.Timestamptz(6)\n  transitionToArchiveAt     DateTime?        @map(\"transition_to_archive_at\") @db.Timestamptz(6)\n  transitionToDeepArchiveAt DateTime?        @map(\"transition_to_deep_archive_at\") @db.Timestamptz(6)\n  transitionToArchiveIRAt   DateTime?        @map(\"transition_to_archive_ir_at\") @db.Timestamptz(6)\n  env                       FileEnvType      @default(prod)\n  vendor                    FileBucketVendor @default(us3)\n  region                    String           @default(\"cn-beijing\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // Relations\n  userAvatars      UserInfo[]\n  personaTemplates PersonaTemplate[]\n  botAvatars       Bot[]\n\n  @@index([fsize, sha256])\n  @@index([isDeleted])\n  @@index([isUploaded])\n  @@index([bucket])\n  @@index([key])\n  @@map(\"f_file_source\")\n}\n\nmodel CountryCode {\n  id        String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  continent String    @db.VarChar(10) // us, eu, ap, cn\n  code      String    @db.VarChar(10) // 国家代码，如 CN, US, SG\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  @@unique([continent, code])\n  @@index([continent])\n  @@index([code])\n  @@map(\"country_code\")\n}\n\n// ============================================================================\n// Bot Management System - Bot 管理系统\n// ============================================================================\n\nenum BotStatus {\n  draft // 草稿状态，未配置完成\n  created\n  starting\n  running\n  stopped\n  error\n\n  @@map(\"bot_status\")\n}\n\n/// Bot 健康状态\nenum HealthStatus {\n  HEALTHY\n  UNHEALTHY\n  UNKNOWN\n\n  @@map(\"health_status\")\n}\n\n/// Bot 类型 - Bot 容器类型\n/// 决定使用哪种 Docker 镜像运行 Bot\nenum BotType {\n  GATEWAY // 主 Gateway bot（默认）- 使用 openclaw:local 镜像\n  TOOL_SANDBOX // 工具沙箱容器 - 使用 openclaw-sandbox 镜像\n  BROWSER_SANDBOX // 浏览器沙箱容器 - 使用 openclaw-sandbox-browser 镜像，支持 VNC\n\n  @@map(\"bot_type\")\n}\n\n/// Bot - 机器人实体\n/// 管理 AI 机器人的生命周期和配置\n/// 注意：aiProvider、model、channelType 字段已移除，这些值从 BotModel 和 BotChannel 动态派生\nmodel Bot {\n  id                String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name              String    @db.VarChar(255)\n  hostname          String    @db.VarChar(64)\n  containerId       String?   @map(\"container_id\") @db.VarChar(255)\n  port              Int?\n  gatewayToken      String?   @map(\"gateway_token\") @db.VarChar(255)\n  proxyTokenHash    String?   @map(\"proxy_token_hash\") @db.VarChar(64)\n  tags              String[]\n  status            BotStatus @default(created)\n  createdById       String    @map(\"created_by_id\") @db.Uuid\n  personaTemplateId String?   @map(\"persona_template_id\") @db.Uuid\n  emoji             String?   @db.VarChar(10)\n  avatarFileId      String?   @map(\"avatar_file_id\") @db.Uuid\n  soulMarkdown      String?   @map(\"soul_markdown\") @db.Text\n\n  // 待生效配置：存储修改后尚未重启生效的配置\n  // 包含 name, tags, soulMarkdown, emoji 等字段的待生效值\n  pendingConfig Json? @map(\"pending_config\") @db.JsonB\n\n  // 健康检查字段\n  healthStatus    HealthStatus @default(UNKNOWN) @map(\"health_status\")\n  lastHealthCheck DateTime?    @map(\"last_health_check\") @db.Timestamptz(6)\n\n  // Bot 类型字段 - 决定使用哪种 Docker 镜像\n  botType BotType @default(GATEWAY) @map(\"bot_type\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // Relations\n  createdBy            UserInfo              @relation(fields: [createdById], references: [id])\n  personaTemplate      PersonaTemplate?      @relation(fields: [personaTemplateId], references: [id], onDelete: SetNull)\n  avatarFile           FileSource?           @relation(fields: [avatarFileId], references: [id], onDelete: SetNull)\n  usageLogs            BotUsageLog[]\n  proxyToken           ProxyToken?\n  plugins              BotPlugin[]\n  skills               BotSkill[]\n  channels             BotChannel[]\n  modelRoutings        BotModelRouting[]\n  routingConfig        BotRoutingConfig?\n  models               BotModel[]\n  feishuPairingRecords FeishuPairingRecord[]\n\n  @@index([status])\n  @@index([hostname])\n  @@index([createdById])\n  @@index([personaTemplateId])\n  @@index([avatarFileId])\n  @@index([isDeleted])\n  @@index([healthStatus])\n  @@index([botType])\n  @@map(\"b_bot\")\n}\n\n/// ProviderKey - AI 提供商 API 密钥\n/// 存储加密的 API 密钥，支持多提供商和标签路由\n/// ProviderKey - API 密钥配置\n/// 存储用户配置的各类 AI 服务商 API 密钥\n/// 支持 OpenAI、Anthropic、Google、DeepSeek 等主流服务商，以及自定义服务商\nmodel ProviderKey {\n  /// 主键 UUID\n  id              String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 服务商标识：openai, anthropic, google, venice, deepseek, groq, custom 等\n  vendor          String  @db.VarChar(50)\n  /// API 协议类型：openai, anthropic, gemini, azure-openai, aws-bedrock, vertexai, ollama, new-api, gateway 等\n  /// 用于确定 API 调用方式，custom 服务商必填\n  apiType         String? @map(\"api_type\") @db.VarChar(50)\n  /// 加密存储的 API 密钥（AES-256-GCM 加密）\n  secretEncrypted Bytes   @map(\"secret_encrypted\")\n  /// 密钥名称（必填），用于用户识别不同密钥，同一用户下唯一\n  label           String  @db.VarChar(255)\n  /// 路由标签，用于在多密钥场景下进行流量分配\n  tag             String? @db.VarChar(100)\n  /// 自定义 API 地址，用于私有部署或代理服务\n  baseUrl         String? @map(\"base_url\") @db.VarChar(500)\n  /// 额外配置（JSON），存储 provider 特定的参数，如 MiniMax 的 groupId\n  metadata        Json?   @map(\"metadata\") @db.JsonB\n  /// 创建者用户 ID\n  createdById     String  @map(\"created_by_id\") @db.Uuid\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // Relations\n  createdBy         UserInfo            @relation(fields: [createdById], references: [id])\n  usageLogs         BotUsageLog[]\n  proxyTokens       ProxyToken[]\n  modelAvailability ModelAvailability[]\n\n  @@unique([createdById, label], name: \"provider_key_user_label_unique\")\n  @@index([vendor])\n  @@index([apiType])\n  @@index([tag])\n  @@index([createdById])\n  @@index([isDeleted])\n  @@map(\"b_provider_key\")\n}\n\n/// BotModel - Bot 与模型的关联表\n/// 存储 Bot 可以使用的模型列表\n/// 普通用户只需要关心模型，不需要了解 Provider 概念\nmodel BotModel {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId     String   @map(\"bot_id\") @db.Uuid\n  /// 模型标识符，如 \"gpt-4o\", \"claude-sonnet-4-20250514\"\n  modelId   String   @map(\"model_id\") @db.VarChar(100)\n  /// 是否启用该模型\n  isEnabled Boolean  @default(true) @map(\"is_enabled\")\n  /// 是否为主模型（Bot 默认使用的模型）\n  isPrimary Boolean  @default(false) @map(\"is_primary\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  bot Bot @relation(fields: [botId], references: [id], onDelete: Cascade)\n\n  @@unique([botId, modelId])\n  @@index([botId])\n  @@index([modelId])\n  @@map(\"b_bot_model\")\n}\n\n/// 模型类型枚举\n/// 用于分类模型的能力类型（与 provider.schema.ts 中的 ModelTypeSchema 保持一致）\nenum ModelType {\n  llm            @map(\"llm\") // 大语言模型\n  text_embedding @map(\"text-embedding\") // 文本嵌入\n  speech2text    @map(\"speech2text\") // 语音转文字\n  tts            @map(\"tts\") // 文字转语音\n  moderation     @map(\"moderation\") // 内容审核\n  rerank         @map(\"rerank\") // 重排序\n  image          @map(\"image\") // 图像生成\n  video          @map(\"video\") // 视频生成\n\n  @@map(\"model_type\")\n}\n\n/// ModelAvailability - 模型可用性缓存表\n/// 缓存 API Key 验证结果，避免频繁调用外部 API\n/// vendor 信息从关联的 ProviderKey 中获取，避免数据冗余\nmodel ModelAvailability {\n  id             String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 模型标识符，如 \"gpt-4o\", \"claude-sonnet-4-20250514\"（反范式化冗余，与 ModelCatalog.model 一致）\n  model          String    @db.VarChar(100)\n  /// 关联的 Provider Key（vendor 信息从这里获取）\n  providerKeyId  String    @map(\"provider_key_id\") @db.Uuid\n  /// 关联的 ModelCatalog ID（必填，模型发现时自动创建 catalog）\n  modelCatalogId String    @map(\"model_catalog_id\") @db.Uuid\n  /// 模型类型（llm, image, video, tts, embedding 等）\n  modelType      ModelType @default(llm) @map(\"model_type\")\n  /// 模型是否可用（API Key 验证通过）\n  isAvailable    Boolean   @default(false) @map(\"is_available\")\n  /// 最后验证时间\n  lastVerifiedAt DateTime  @map(\"last_verified_at\") @db.Timestamptz(6)\n  /// 验证失败时的错误信息\n  errorMessage   String?   @map(\"error_message\") @db.Text\n\n  // ============ Vendor 级别特有配置 ============\n  /// 该 vendor 实例的优先级（用于同模型多 vendor 时的选择）\n  vendorPriority Int @default(0) @map(\"vendor_priority\")\n  /// 该 vendor 实例的健康评分（基于历史成功率动态计算）\n  healthScore    Int @default(100) @map(\"health_score\")\n\n  // ============ 协议适配配置（双层模型体系）============\n  /// 模型支持的协议类型列表（从 ModelCatalog 同步）\n  /// 如 [\"openai\", \"anthropic\"] 表示同时支持 OpenAI 和 Anthropic 协议\n  supportedApiTypes String[] @default([\"openai\"]) @map(\"supported_api_types\")\n  /// 用户优先选择的协议类型（可选，默认使用 Provider 默认协议）\n  /// 用于第二层（研究 Agent）模型选择使用 Anthropic 协议\n  preferredApiType  String?  @map(\"preferred_api_type\") @db.VarChar(50)\n\n  // ============ 协议级别 BaseUrl 配置 ============\n  /// 按协议类型配置的 BaseUrl\n  /// JSON 格式：{ \"openai\": \"https://...\", \"anthropic\": \"https://...\" }\n  /// 未配置的协议使用 ProviderKey.baseUrl\n  apiTypeBaseUrls Json? @map(\"api_type_base_urls\") @db.JsonB\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  providerKey  ProviderKey  @relation(fields: [providerKeyId], references: [id], onDelete: Cascade)\n  modelCatalog ModelCatalog @relation(fields: [modelCatalogId], references: [id], onDelete: Restrict)\n\n  @@unique([providerKeyId, model])\n  @@index([model])\n  @@index([modelCatalogId])\n  @@index([modelType])\n  @@index([isAvailable])\n  @@index([preferredApiType])\n  @@map(\"b_model_availability\")\n}\n\n/// ModelCapabilityTag - 模型与能力标签的关联表\n/// 存储模型（非 vendor 实例）与能力标签的多对多关系，支持匹配来源追踪\nmodel ModelCapabilityTag {\n  id              String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 关联的 ModelCatalog ID（模型级别）\n  modelCatalogId  String   @map(\"model_catalog_id\") @db.Uuid\n  /// 关联的 CapabilityTag ID\n  capabilityTagId String   @map(\"capability_tag_id\") @db.Uuid\n  /// 匹配来源：pattern (模式匹配), feature (特性匹配), scenario (场景匹配), manual (手动)\n  matchSource     String   @default(\"pattern\") @map(\"match_source\") @db.VarChar(20)\n  /// 匹配置信度 (0-100)\n  confidence      Int      @default(100)\n  createdAt       DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  modelCatalog  ModelCatalog  @relation(fields: [modelCatalogId], references: [id], onDelete: Cascade)\n  capabilityTag CapabilityTag @relation(fields: [capabilityTagId], references: [id], onDelete: Cascade)\n\n  @@unique([modelCatalogId, capabilityTagId])\n  @@index([modelCatalogId])\n  @@index([capabilityTagId])\n  @@index([matchSource])\n  @@map(\"b_model_capability_tag\")\n}\n\n/// BotUsageLog - Bot API 使用日志\n/// 记录每次 API 调用的使用情况\nmodel BotUsageLog {\n  id             String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId          String   @map(\"bot_id\") @db.Uuid\n  vendor         String   @db.VarChar(50)\n  providerKeyId  String?  @map(\"provider_key_id\") @db.Uuid\n  statusCode     Int?     @map(\"status_code\")\n  requestTokens  Int?     @map(\"request_tokens\")\n  responseTokens Int?     @map(\"response_tokens\")\n  createdAt      DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  // 基础字段 - 用于精细化用量分析\n  model        String? @db.VarChar(100) // AI 模型名称\n  endpoint     String? @db.VarChar(255) // API 端点路径\n  durationMs   Int?    @map(\"duration_ms\") // 请求耗时（毫秒）\n  errorMessage String? @map(\"error_message\") @db.Text // 错误信息\n\n  // ============ 混合架构扩展字段 ============\n  // 原生功能使用追踪\n  /// Extended Thinking tokens\n  thinkingTokens   Int? @map(\"thinking_tokens\")\n  /// Cache Control 读取 tokens\n  cacheReadTokens  Int? @map(\"cache_read_tokens\")\n  /// Cache Control 写入 tokens\n  cacheWriteTokens Int? @map(\"cache_write_tokens\")\n\n  /// 协议类型：openai-compatible | anthropic-native | gemini-native\n  protocolType String? @map(\"protocol_type\") @db.VarChar(50)\n\n  // 成本追踪（美元）\n  /// 输入成本\n  inputCost    Decimal? @map(\"input_cost\") @db.Decimal(10, 6)\n  /// 输出成本\n  outputCost   Decimal? @map(\"output_cost\") @db.Decimal(10, 6)\n  /// 思考成本\n  thinkingCost Decimal? @map(\"thinking_cost\") @db.Decimal(10, 6)\n  /// 缓存成本\n  cacheCost    Decimal? @map(\"cache_cost\") @db.Decimal(10, 6)\n  /// 总成本\n  totalCost    Decimal? @map(\"total_cost\") @db.Decimal(10, 6)\n\n  // Fallback 追踪\n  /// 是否使用了 Fallback\n  fallbackUsed  Boolean? @map(\"fallback_used\")\n  /// Fallback 级别（0=主模型，1=第一备用，以此类推）\n  fallbackLevel Int?     @map(\"fallback_level\")\n  /// 原始请求模型\n  originalModel String?  @map(\"original_model\") @db.VarChar(100)\n\n  bot         Bot          @relation(fields: [botId], references: [id], onDelete: Cascade)\n  providerKey ProviderKey? @relation(fields: [providerKeyId], references: [id], onDelete: SetNull)\n\n  @@index([botId])\n  @@index([createdAt])\n  @@index([vendor])\n  @@index([botId, createdAt]) // 复合索引：按 Bot 查询时间范围\n  @@index([botId, vendor, createdAt]) // 复合索引：按 Bot+Vendor 查询\n  @@index([model]) // 按模型查询\n  @@index([protocolType]) // 按协议类型查询\n  @@index([fallbackUsed]) // 按 Fallback 使用情况查询\n  @@map(\"b_usage_log\")\n}\n\n// ============================================================================\n// Zero-Trust Mode - Proxy Token System\n// ============================================================================\n\n/// ProxyToken - Zero-Trust 模式的代理令牌\n/// Bot 容器使用此令牌通过 Proxy 访问 AI API，而不直接持有 API Key\n/// 核心安全原则：Bot 容器永远不持有真实的 API Key\nmodel ProxyToken {\n  id           String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 关联的 Bot ID（一对一关系）\n  botId        String    @unique @map(\"bot_id\") @db.Uuid\n  /// Token 的 SHA-256 哈希值（永不存储原始 Token）\n  tokenHash    String    @unique @map(\"token_hash\") @db.VarChar(64)\n  /// AI 服务商标识（openai, anthropic, google 等）\n  vendor       String    @db.VarChar(50)\n  /// 关联的 ProviderKey ID\n  keyId        String    @map(\"key_id\") @db.Uuid\n  /// 访问控制标签\n  tags         String[]\n  /// Token 过期时间（可选）\n  expiresAt    DateTime? @map(\"expires_at\") @db.Timestamptz(6)\n  /// Token 撤销时间（null 表示有效）\n  revokedAt    DateTime? @map(\"revoked_at\") @db.Timestamptz(6)\n  /// 最后使用时间\n  lastUsedAt   DateTime? @map(\"last_used_at\") @db.Timestamptz(6)\n  /// 请求计数\n  requestCount Int       @default(0) @map(\"request_count\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  // Relations\n  bot         Bot         @relation(fields: [botId], references: [id], onDelete: Cascade)\n  providerKey ProviderKey @relation(fields: [keyId], references: [id], onDelete: Cascade)\n\n  @@index([tokenHash])\n  @@index([botId])\n  @@index([keyId])\n  @@index([vendor])\n  @@index([expiresAt])\n  @@index([revokedAt])\n  @@map(\"b_proxy_token\")\n}\n\n/// User Message System\n/// 用户消息系统 - 支持系统通知、用户间消息等\nmodel Message {\n  id        String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  type      String    @db.VarChar(50) // SYSTEM, USER, NOTIFICATION, MILESTONE, ACHIEVEMENT\n  title     String?   @db.VarChar(255)\n  content   Json // 消息内容（支持富文本、多语言）\n  senderId  String?   @map(\"sender_id\") @db.Uuid // null for system messages\n  metadata  Json? // 额外元数据（如关联的问题ID、徽章ID等）\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  sender     UserInfo?          @relation(\"SentMessages\", fields: [senderId], references: [id], onDelete: SetNull)\n  recipients MessageRecipient[]\n\n  @@index([type])\n  @@index([senderId])\n  @@index([createdAt])\n  @@index([isDeleted])\n  @@map(\"message\")\n}\n\n/// Message Recipient - 消息接收记录\n/// 记录每个用户接收到的消息及其阅读状态\nmodel MessageRecipient {\n  id        String    @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  messageId String    @map(\"message_id\") @db.Uuid\n  userId    String    @map(\"user_id\") @db.Uuid\n  isRead    Boolean   @default(false) @map(\"is_read\")\n  readAt    DateTime? @map(\"read_at\") @db.Timestamptz(6)\n\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  message Message  @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  user    UserInfo @relation(\"ReceivedMessages\", fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([messageId, userId])\n  @@index([userId, isRead])\n  @@index([messageId])\n  @@index([isDeleted])\n  @@index([userId, isRead, isDeleted]) // Composite index for unread message count queries\n  @@map(\"message_recipient\")\n}\n\n// ============================================================================\n// Operation Log System - 操作日志系统\n// ============================================================================\n\nenum OperateType {\n  CREATE\n  UPDATE\n  DELETE\n  LOGIN\n  LOGOUT\n  START\n  STOP\n  EXPORT\n  IMPORT\n\n  @@map(\"operate_type\")\n}\n\nenum OperateTarget {\n  BOT\n  PROVIDER_KEY\n  USER\n  PERSONA_TEMPLATE\n  SYSTEM\n\n  @@map(\"operate_target\")\n}\n\n/// OperateLog - 操作日志\n/// 记录用户的操作行为，用于审计和追踪\nmodel OperateLog {\n  id          String        @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  userId      String        @map(\"user_id\") @db.Uuid\n  operateType OperateType   @map(\"operate_type\")\n  target      OperateTarget\n  targetId    String?       @map(\"target_id\") @db.Uuid\n  targetName  String?       @map(\"target_name\") @db.VarChar(255)\n  detail      Json?\n  ipAddress   String?       @map(\"ip_address\") @db.VarChar(45)\n  userAgent   String?       @map(\"user_agent\") @db.VarChar(500)\n  createdAt   DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  user UserInfo @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([operateType])\n  @@index([target])\n  @@index([targetId])\n  @@index([createdAt(sort: Desc)])\n  @@map(\"operate_log\")\n}\n\n// ============================================================================\n// Channel Definition System - 渠道定义系统\n// ============================================================================\n\n/// ChannelDefinition - 渠道定义\n/// 存储各种消息渠道的配置信息，包括所需的凭证字段\nmodel ChannelDefinition {\n  id               String   @id @db.VarChar(50) // e.g., \"feishu\", \"telegram\", \"discord\"\n  label            String   @db.VarChar(100) // Display name\n  icon             String   @db.VarChar(10) // Emoji or short icon code\n  popular          Boolean  @default(false) // Whether to show in popular section (default/fallback)\n  popularLocales   String[] @default([]) @map(\"popular_locales\") // Locales where this channel is popular, e.g., [\"zh-CN\", \"en\"]\n  tokenHint        String   @map(\"token_hint\") @db.VarChar(500) // Help text for token\n  tokenPlaceholder String   @map(\"token_placeholder\") @db.VarChar(255) // Placeholder text\n  helpUrl          String?  @map(\"help_url\") @db.VarChar(500) // Documentation URL\n  helpText         String?  @map(\"help_text\") @db.VarChar(255) // Help link text\n  sortOrder        Int      @default(0) @map(\"sort_order\") // Display order\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  credentialFields ChannelCredentialField[]\n\n  @@index([popular])\n  @@index([sortOrder])\n  @@index([isDeleted])\n  @@map(\"b_channel_definition\")\n}\n\n/// ChannelCredentialField - 渠道凭证字段\n/// 定义每个渠道所需的凭证字段配置\nmodel ChannelCredentialField {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  channelId   String  @map(\"channel_id\") @db.VarChar(50)\n  key         String  @db.VarChar(50) // Field key, e.g., \"appId\", \"appSecret\"\n  label       String  @db.VarChar(100) // Display label\n  placeholder String  @db.VarChar(255) // Placeholder text\n  fieldType   String  @default(\"text\") @map(\"field_type\") @db.VarChar(20) // \"text\" or \"password\"\n  required    Boolean @default(true) // Whether field is required\n  sortOrder   Int     @default(0) @map(\"sort_order\") // Display order within channel\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  channel ChannelDefinition @relation(fields: [channelId], references: [id], onDelete: Cascade)\n\n  @@unique([channelId, key])\n  @@index([channelId])\n  @@index([sortOrder])\n  @@index([isDeleted])\n  @@map(\"b_channel_credential_field\")\n}\n\n// ============================================================================\n// Plugin System - 插件系统\n// ============================================================================\n\n/// 插件分类\nenum PluginCategory {\n  BROWSER // 浏览器自动化\n  FILESYSTEM // 文件系统\n  DATABASE // 数据库\n  API // API 集成\n  COMMUNICATION // 通讯工具\n  DEVELOPMENT // 开发工具\n  CUSTOM // 自定义\n\n  @@map(\"plugin_category\")\n}\n\n/// Plugin - 插件定义\n/// 存储插件的元数据和配置模板\nmodel Plugin {\n  id            String         @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name          String         @db.VarChar(100)\n  slug          String         @unique @db.VarChar(100)\n  description   String?        @db.Text\n  version       String         @db.VarChar(20)\n  author        String?        @db.VarChar(100)\n  category      PluginCategory\n  region        String         @default(\"global\") @db.VarChar(20) // global, cn, en\n  configSchema  Json?          @map(\"config_schema\") // JSON Schema for plugin config\n  defaultConfig Json?          @map(\"default_config\") // Default configuration\n  mcpConfig     Json?          @map(\"mcp_config\") // MCP server configuration\n  isOfficial    Boolean        @default(false) @map(\"is_official\")\n  isEnabled     Boolean        @default(true) @map(\"is_enabled\")\n  downloadUrl   String?        @map(\"download_url\") @db.VarChar(500)\n  iconEmoji     String?        @map(\"icon_emoji\") @db.VarChar(10)\n  iconUrl       String?        @map(\"icon_url\") @db.VarChar(500)\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  installations BotPlugin[]\n\n  @@index([category])\n  @@index([region])\n  @@index([isOfficial])\n  @@index([isEnabled])\n  @@index([isDeleted])\n  @@map(\"b_plugin\")\n}\n\n/// BotPlugin - Bot 与 Plugin 的关联表\n/// 记录 Bot 安装的插件及其配置\nmodel BotPlugin {\n  id        String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId     String   @map(\"bot_id\") @db.Uuid\n  pluginId  String   @map(\"plugin_id\") @db.Uuid\n  config    Json? // Plugin instance configuration\n  isEnabled Boolean  @default(true) @map(\"is_enabled\")\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  bot    Bot    @relation(fields: [botId], references: [id], onDelete: Cascade)\n  plugin Plugin @relation(fields: [pluginId], references: [id], onDelete: Cascade)\n\n  @@unique([botId, pluginId])\n  @@index([botId])\n  @@index([pluginId])\n  @@index([isEnabled])\n  @@map(\"b_bot_plugin\")\n}\n\n/// SkillType - 技能类型/分类\n/// 用于对技能进行分类管理，支持中英文名称\nmodel SkillType {\n  id            String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 类型标识（如 coding-agents, git-github）\n  slug          String  @unique @db.VarChar(100)\n  /// 英文名称（如 Coding Agents & IDEs）\n  name          String  @db.VarChar(200)\n  /// 中文名称\n  nameZh        String? @map(\"name_zh\") @db.VarChar(200)\n  /// 英文描述\n  description   String? @db.Text\n  /// 中文描述\n  descriptionZh String? @map(\"description_zh\") @db.Text\n  /// 图标（emoji 或图标名称）\n  icon          String? @db.VarChar(50)\n  /// 排序权重（越小越靠前）\n  sortOrder     Int     @default(0) @map(\"sort_order\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  skills Skill[]\n\n  @@index([slug])\n  @@index([sortOrder])\n  @@index([isDeleted])\n  @@map(\"b_skill_type\")\n}\n\n/// Skill - 自定义技能定义\n/// 用户可以创建自定义技能供 Bot 使用\n/// 支持系统预设、用户自定义和外部同步（如 OpenClaw）\nmodel Skill {\n  id            String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  name          String  @db.VarChar(100)\n  /// 中文名称（翻译自 name）\n  nameZh        String? @map(\"name_zh\") @db.VarChar(200)\n  slug          String  @db.VarChar(100)\n  /// 英文描述（原始描述）\n  description   String? @db.Text\n  /// 中文描述（翻译自 description）\n  descriptionZh String? @map(\"description_zh\") @db.Text\n  version       String  @default(\"1.0.0\") @db.VarChar(20)\n  /// 最新可用版本（来自 _meta.json）\n  latestVersion String? @map(\"latest_version\") @db.VarChar(20)\n\n  // 技能类型关联\n  skillTypeId String?    @map(\"skill_type_id\") @db.Uuid\n  skillType   SkillType? @relation(fields: [skillTypeId], references: [id], onDelete: SetNull)\n\n  // 技能定义 (JSON)\n  // 对于 tool 类型: { name, description, inputSchema, handler }\n  // 对于 prompt 类型: { template, variables }\n  // 对于 workflow 类型: { steps, triggers }\n  definition Json @db.JsonB\n\n  // 示例用法\n  examples Json? @db.JsonB\n\n  // 是否为系统预设\n  isSystem  Boolean @default(false) @map(\"is_system\")\n  isEnabled Boolean @default(true) @map(\"is_enabled\")\n\n  // 创建者\n  createdById String? @map(\"created_by_id\") @db.Uuid\n\n  // ============ 外部来源字段（用于同步 OpenClaw 等外部技能库）============\n  /// 外部来源标识（如 openclaw, clawhub）\n  source       String?   @db.VarChar(50)\n  /// 外部来源 URL（如 GitHub 仓库链接）\n  sourceUrl    String?   @map(\"source_url\") @db.VarChar(500)\n  /// 技能作者（外部来源的作者）\n  author       String?   @db.VarChar(100)\n  /// 最后同步时间（元数据同步）\n  lastSyncedAt DateTime? @map(\"last_synced_at\") @db.Timestamptz(6)\n\n  // ============ 预同步文件目录（用于加速安装）============\n  /// 完整的技能文件目录（从 GitHub 预同步）\n  /// 格式: [{ relativePath: string, content: string, size: number }]\n  files         Json?     @db.JsonB\n  /// 文件目录同步时间\n  filesSyncedAt DateTime? @map(\"files_synced_at\") @db.Timestamptz(6)\n  /// 文件数量\n  fileCount     Int?      @map(\"file_count\")\n  /// 是否包含初始化脚本 (scripts/init.sh)\n  hasInitScript Boolean   @default(false) @map(\"has_init_script\")\n  /// 是否包含参考文档 (references/)\n  hasReferences Boolean   @default(false) @map(\"has_references\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  installations BotSkill[]\n\n  @@unique([slug, createdById])\n  @@unique([source, slug], name: \"b_skill_source_slug_key\")\n  @@index([skillTypeId])\n  @@index([isSystem])\n  @@index([isEnabled])\n  @@index([createdById])\n  @@index([isDeleted])\n  @@index([source])\n  @@index([lastSyncedAt])\n  @@map(\"b_skill\")\n}\n\n/// BotSkill - Bot 与 Skill 的关联表\n/// 记录 Bot 安装的技能及其配置\nmodel BotSkill {\n  id               String   @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId            String   @map(\"bot_id\") @db.Uuid\n  skillId          String   @map(\"skill_id\") @db.Uuid\n  config           Json? // Skill instance configuration overrides\n  /// 安装时的技能版本\n  installedVersion String?  @map(\"installed_version\") @db.VarChar(20)\n  /// 安装的文件数量\n  fileCount        Int?     @map(\"file_count\")\n  /// 是否执行了初始化脚本\n  scriptExecuted   Boolean  @default(false) @map(\"script_executed\")\n  /// 是否包含参考文档\n  hasReferences    Boolean  @default(false) @map(\"has_references\")\n  isEnabled        Boolean  @default(true) @map(\"is_enabled\")\n  createdAt        DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt        DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  bot   Bot   @relation(fields: [botId], references: [id], onDelete: Cascade)\n  skill Skill @relation(fields: [skillId], references: [id], onDelete: Cascade)\n\n  @@unique([botId, skillId])\n  @@index([botId])\n  @@index([skillId])\n  @@index([isEnabled])\n  @@map(\"b_bot_skill\")\n}\n\n// ============================================================================\n// Bot Channel System - Bot 渠道系统\n// ============================================================================\n\n/// 渠道连接状态\nenum ChannelConnectionStatus {\n  DISCONNECTED // 未连接\n  CONNECTING // 连接中\n  CONNECTED // 已连接\n  ERROR // 连接错误\n\n  @@map(\"channel_connection_status\")\n}\n\n// ============================================================================\n// Model Pricing System - AI 模型定价系统\n// ============================================================================\n\n/// ModelPricing - AI 模型定价与能力目录\n/// 存储各 AI 模型的定价信息、能力评分和特性支持，用于成本估算和智能路由\n/// 价格单位：美元/百万 tokens\n/// ModelCatalog - 模型目录（全局模型注册中心）\n/// 以 model 为唯一标识，存储模型身份、定价、能力评分、特性支持等信息\n/// 所有路由配置（能力标签、Fallback、复杂度路由）均引用此表\n/// 原表名 b_model_pricing，重构后升级为 b_model_catalog\nmodel ModelCatalog {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 模型标识符（全局唯一），如 \"gpt-4o\", \"claude-sonnet-4-20250514\"\n  model       String  @unique @db.VarChar(100)\n  /// 原始供应商标识（openai, anthropic, google, deepseek 等）\n  vendor      String  @db.VarChar(50)\n  /// 模型显示名称\n  displayName String? @map(\"display_name\") @db.VarChar(255)\n  /// 模型描述\n  description String? @db.Text\n\n  // ============ 定价信息（美元/百万 tokens）============\n  /// 输入 token 价格\n  inputPrice      Decimal  @map(\"input_price\") @db.Decimal(10, 6)\n  /// 输出 token 价格\n  outputPrice     Decimal  @map(\"output_price\") @db.Decimal(10, 6)\n  /// 缓存读取价格（Anthropic Cache Control）\n  cacheReadPrice  Decimal? @map(\"cache_read_price\") @db.Decimal(10, 6)\n  /// 缓存写入价格（Anthropic Cache Control）\n  cacheWritePrice Decimal? @map(\"cache_write_price\") @db.Decimal(10, 6)\n  /// 思考 token 价格（Anthropic Extended Thinking）\n  thinkingPrice   Decimal? @map(\"thinking_price\") @db.Decimal(10, 6)\n\n  // ============ 能力评分（0-100）============\n  /// 推理能力评分\n  reasoningScore  Int @default(50) @map(\"reasoning_score\")\n  /// 编码能力评分\n  codingScore     Int @default(50) @map(\"coding_score\")\n  /// 创造力评分\n  creativityScore Int @default(50) @map(\"creativity_score\")\n  /// 响应速度评分\n  speedScore      Int @default(50) @map(\"speed_score\")\n  /// 上下文长度（K tokens）\n  contextLength   Int @default(128) @map(\"context_length\")\n\n  // ============ 特性支持 ============\n  /// 是否支持 Extended Thinking（Anthropic）\n  supportsExtendedThinking Boolean @default(false) @map(\"supports_extended_thinking\")\n  /// 是否支持 Cache Control（Anthropic）\n  supportsCacheControl     Boolean @default(false) @map(\"supports_cache_control\")\n  /// 是否支持视觉/多模态\n  supportsVision           Boolean @default(false) @map(\"supports_vision\")\n  /// 是否支持 Function Calling\n  supportsFunctionCalling  Boolean @default(true) @map(\"supports_function_calling\")\n  /// 是否支持流式响应\n  supportsStreaming        Boolean @default(true) @map(\"supports_streaming\")\n\n  // ============ 推荐场景 ============\n  /// 推荐使用场景（JSON 数组）\n  /// 如 [\"deep-reasoning\", \"coding\", \"general-purpose\"]\n  recommendedScenarios Json? @map(\"recommended_scenarios\") @db.JsonB\n\n  // ============ 协议适配配置（双层模型体系）============\n  /// 该模型支持的 API 协议类型列表\n  /// 如 [\"openai\", \"anthropic\"] 表示同时支持 OpenAI 和 Anthropic 协议\n  /// 用于前端显示协议选择器和后端验证\n  supportedApiTypes  String[] @default([\"openai\"]) @map(\"supported_api_types\")\n  /// Anthropic 协议模型标识符（如果与 openai 不同）\n  /// 某些模型在 Anthropic 协议下的名称可能与 OpenAI 不同\n  anthropicModelId   String?  @map(\"anthropic_model_id\") @db.VarChar(100)\n  /// 是否推荐使用 Anthropic 协议\n  /// 用于第二层（研究 Agent）模型，充分利用 Extended Thinking\n  recommendAnthropic Boolean  @default(false) @map(\"recommend_anthropic\")\n  /// 推荐使用 Anthropic 协议的原因\n  /// 如 \"更好的 Extended Thinking 和流式输出支持\"\n  recommendReason    String?  @map(\"recommend_reason\") @db.VarChar(500)\n  /// 模型所属层级：production（第一层）、research（第二层）、both（两者皆可）\n  modelLayer         String   @default(\"production\") @map(\"model_layer\") @db.VarChar(20)\n\n  // ============ 数据来源追踪 ============\n  /// 数据来源：manual (手动), api (API同步), import (导入)\n  dataSource String  @default(\"manual\") @map(\"data_source\") @db.VarChar(20)\n  /// 来源 URL（如果从外部 API 同步）\n  sourceUrl  String? @map(\"source_url\") @db.VarChar(500)\n\n  // ============ 状态 ============\n  /// 是否启用\n  isEnabled       Boolean   @default(true) @map(\"is_enabled\")\n  /// 是否已弃用\n  isDeprecated    Boolean   @default(false) @map(\"is_deprecated\")\n  /// 弃用日期\n  deprecationDate DateTime? @map(\"deprecation_date\") @db.Timestamptz(6)\n  /// 价格更新时间\n  priceUpdatedAt  DateTime  @default(now()) @map(\"price_updated_at\") @db.Timestamptz(6)\n  /// 备注\n  notes           String?   @db.Text\n  /// 其他扩展元数据\n  metadata        Json?     @db.JsonB\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // ============ 关联关系 ============\n  /// 该模型在各 vendor 的可用性记录\n  availabilities            ModelAvailability[]\n  /// 模型能力标签（模型级）\n  capabilityTags            ModelCapabilityTag[]\n  /// Fallback 链引用\n  fallbackChainModels       FallbackChainModel[]\n  /// 复杂度路由引用\n  complexityRoutingMappings ComplexityRoutingModelMapping[]\n\n  @@index([vendor])\n  @@index([isEnabled])\n  @@index([isDeprecated])\n  @@index([isDeleted])\n  @@index([supportsExtendedThinking])\n  @@index([supportsCacheControl])\n  @@index([recommendAnthropic])\n  @@index([modelLayer])\n  @@map(\"b_model_catalog\")\n}\n\n// ============================================================================\n// Model Routing System - 模型路由系统\n// ============================================================================\n\n/// 路由类型枚举\nenum ModelRoutingType {\n  FUNCTION_ROUTE // 功能路由：根据消息内容选择模型\n  LOAD_BALANCE // 负载均衡：多模型分流\n  FAILOVER // 故障转移：主备切换\n\n  @@map(\"model_routing_type\")\n}\n\n/// BotModelRouting - Bot 模型路由配置\n/// 存储 Bot 的模型路由规则，支持功能路由、负载均衡、故障转移\nmodel BotModelRouting {\n  id          String           @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId       String           @map(\"bot_id\") @db.Uuid\n  /// 路由类型\n  routingType ModelRoutingType @map(\"routing_type\")\n  /// 路由名称（用于标识）\n  name        String           @db.VarChar(100)\n  /// 路由配置 (JSON)\n  /// 功能路由: { rules: [...], defaultTarget: {...} }\n  /// 负载均衡: { strategy: \"round_robin\"|\"weighted\"|\"least_latency\", targets: [...] }\n  /// 故障转移: { primary: {...}, fallbackChain: [...], retry: {...} }\n  config      Json             @db.JsonB\n  /// 优先级（数字越小优先级越高）\n  priority    Int              @default(100)\n  /// 是否启用\n  isEnabled   Boolean          @default(true) @map(\"is_enabled\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  bot Bot @relation(fields: [botId], references: [id], onDelete: Cascade)\n\n  @@index([botId])\n  @@index([routingType])\n  @@index([priority])\n  @@index([isEnabled])\n  @@index([isDeleted])\n  @@map(\"b_bot_model_routing\")\n}\n\n/// BotChannel - Bot 渠道配置\n/// 存储 Bot 的渠道连接配置，包括加密的凭证\n/// 一个 Bot 可以连接多个渠道（如同时连接飞书和 Telegram）\nmodel BotChannel {\n  id                   String                  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId                String                  @map(\"bot_id\") @db.Uuid\n  channelType          String                  @map(\"channel_type\") @db.VarChar(50) // feishu, telegram, discord, etc.\n  name                 String                  @db.VarChar(255) // 渠道名称，用于区分同类型多个渠道\n  credentialsEncrypted Bytes                   @map(\"credentials_encrypted\") // AES-256-GCM 加密的凭证 JSON\n  config               Json? // 渠道特定配置（如 requireMention, replyInThread 等）\n  isEnabled            Boolean                 @default(true) @map(\"is_enabled\")\n  connectionStatus     ChannelConnectionStatus @default(DISCONNECTED) @map(\"connection_status\")\n  lastConnectedAt      DateTime?               @map(\"last_connected_at\") @db.Timestamptz(6)\n  lastError            String?                 @map(\"last_error\") @db.Text\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  bot                  Bot                   @relation(fields: [botId], references: [id], onDelete: Cascade)\n  feishuPairingRecords FeishuPairingRecord[]\n\n  @@unique([botId, channelType, name])\n  @@index([botId])\n  @@index([channelType])\n  @@index([isEnabled])\n  @@index([connectionStatus])\n  @@index([isDeleted])\n  @@map(\"b_bot_channel\")\n}\n\n// ============================================================================\n// Channel Pairing System - 渠道配对系统\n// ============================================================================\n\n/// PairingStatus - 配对状态\nenum PairingStatus {\n  PENDING // 待处理\n  APPROVED // 已批准\n  REJECTED // 已拒绝\n  EXPIRED // 已过期\n\n  @@map(\"pairing_status\")\n}\n\n/// FeishuPairingRecord - 飞书配对记录\n/// 持久化存储飞书用户的配对信息和用户基本信息\n/// 启动时与文件系统 pairing.json 同步，数据库为最高优先级\nmodel FeishuPairingRecord {\n  id String @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n\n  // ============ 关联 ============\n  botId        String @map(\"bot_id\") @db.Uuid\n  botChannelId String @map(\"bot_channel_id\") @db.Uuid\n\n  // ============ 配对信息 ============\n  /// 配对码（6-8位大写字母数字）\n  code         String        @db.VarChar(8)\n  /// 飞书用户 Open ID\n  feishuOpenId String        @map(\"feishu_open_id\") @db.VarChar(100)\n  /// 配对状态\n  status       PairingStatus @default(PENDING)\n\n  // ============ 飞书用户信息 ============\n  /// 用户名称\n  userName           String? @map(\"user_name\") @db.VarChar(255)\n  /// 用户英文名\n  userNameEn         String? @map(\"user_name_en\") @db.VarChar(255)\n  /// 用户头像 URL\n  userAvatarUrl      String? @map(\"user_avatar_url\") @db.VarChar(500)\n  /// 用户邮箱\n  userEmail          String? @map(\"user_email\") @db.VarChar(255)\n  /// 用户手机号\n  userMobile         String? @map(\"user_mobile\") @db.VarChar(50)\n  /// 用户部门 ID\n  userDepartmentId   String? @map(\"user_department_id\") @db.VarChar(100)\n  /// 用户部门名称\n  userDepartmentName String? @map(\"user_department_name\") @db.VarChar(255)\n  /// 原始用户信息（JSON，存储完整的飞书用户信息）\n  userInfoRaw        Json?   @map(\"user_info_raw\") @db.JsonB\n\n  // ============ 时间戳 ============\n  /// 配对请求创建时间\n  expiresAt    DateTime  @map(\"expires_at\") @db.Timestamptz(6)\n  /// 批准时间\n  approvedAt   DateTime? @map(\"approved_at\") @db.Timestamptz(6)\n  /// 批准人 ID\n  approvedById String?   @map(\"approved_by_id\") @db.Uuid\n  /// 拒绝时间\n  rejectedAt   DateTime? @map(\"rejected_at\") @db.Timestamptz(6)\n  /// 拒绝人 ID\n  rejectedById String?   @map(\"rejected_by_id\") @db.Uuid\n  /// 最后从飞书同步用户信息的时间\n  lastSyncedAt DateTime? @map(\"last_synced_at\") @db.Timestamptz(6)\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  // Relations\n  bot        Bot        @relation(fields: [botId], references: [id], onDelete: Cascade)\n  botChannel BotChannel @relation(fields: [botChannelId], references: [id], onDelete: Cascade)\n\n  @@unique([botId, code])\n  @@unique([botId, feishuOpenId])\n  @@index([botId])\n  @@index([botChannelId])\n  @@index([code])\n  @@index([feishuOpenId])\n  @@index([status])\n  @@index([isDeleted])\n  @@map(\"b_feishu_pairing_record\")\n}\n\n// ============================================================================\n// Hybrid Architecture - Routing Configuration System\n// 混合架构 - 路由配置系统\n// ============================================================================\n\n/// CapabilityTag - 能力标签\n/// 定义路由能力标签及其要求，用于智能路由决策\nmodel CapabilityTag {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 标签标识（如 deep-reasoning, cost-optimized, web-search）\n  tagId       String  @unique @map(\"tag_id\") @db.VarChar(50)\n  /// 显示名称\n  name        String  @db.VarChar(100)\n  /// 标签描述\n  description String? @db.Text\n\n  /// 分类：reasoning | search | code | vision | audio | cost | context\n  category String @db.VarChar(50)\n\n  /// 路由优先级（数值越高优先级越高）\n  priority Int @default(50)\n\n  // ============ 路由要求 ============\n  /// 要求的协议类型：openai-compatible | anthropic-native | null\n  requiredProtocol String? @map(\"required_protocol\") @db.VarChar(50)\n  /// 要求的 Skills（JSON 数组）如 [\"web_search\", \"code_runner\"]\n  requiredSkills   Json?   @map(\"required_skills\") @db.JsonB\n  /// 要求的模型列表（JSON 数组）如 [\"claude-sonnet-4-*\", \"gpt-4o\"]\n  requiredModels   Json?   @map(\"required_models\") @db.JsonB\n\n  // ============ 特性要求 ============\n  /// 是否要求 Extended Thinking\n  requiresExtendedThinking Boolean @default(false) @map(\"requires_extended_thinking\")\n  /// 是否要求 Cache Control\n  requiresCacheControl     Boolean @default(false) @map(\"requires_cache_control\")\n  /// 是否要求视觉能力\n  requiresVision           Boolean @default(false) @map(\"requires_vision\")\n\n  /// 单次请求最大成本约束（美元）\n  maxCostPerMToken Decimal? @map(\"max_cost_per_m_token\") @db.Decimal(10, 6)\n\n  // ============ 状态 ============\n  /// 是否启用\n  isActive  Boolean @default(true) @map(\"is_active\")\n  /// 是否为内置标签\n  isBuiltin Boolean @default(false) @map(\"is_builtin\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  modelCapabilityTags ModelCapabilityTag[]\n\n  @@index([category])\n  @@index([isActive])\n  @@index([isBuiltin])\n  @@index([isDeleted])\n  @@map(\"b_capability_tag\")\n}\n\n/// FallbackChain - Fallback 链配置\n/// 定义模型降级策略，支持多模型故障转移\nmodel FallbackChain {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 链标识（如 default, deep-reasoning, cost-optimized）\n  chainId     String  @unique @map(\"chain_id\") @db.VarChar(50)\n  /// 显示名称\n  name        String  @db.VarChar(100)\n  /// 链描述\n  description String? @db.Text\n\n  /// @deprecated 旧的 JSON 模型链配置，迁移到 FallbackChainModel 关联表后移除\n  /// [{ vendor: \"anthropic\", model: \"claude-sonnet-4\", protocol: \"anthropic-native\", features: {...} }]\n  models Json? @db.JsonB\n\n  // 新：通过关联表引用实际可用模型\n  chainModels FallbackChainModel[]\n\n  // ============ 触发条件 ============\n  /// 触发 Fallback 的 HTTP 状态码（JSON 数组）\n  triggerStatusCodes Json @default(\"[429, 500, 502, 503, 504]\") @map(\"trigger_status_codes\") @db.JsonB\n  /// 触发 Fallback 的错误类型（JSON 数组）\n  triggerErrorTypes  Json @default(\"[\\\"rate_limit\\\", \\\"overloaded\\\", \\\"timeout\\\"]\") @map(\"trigger_error_types\") @db.JsonB\n  /// 触发 Fallback 的超时时间（毫秒）\n  triggerTimeoutMs   Int  @default(60000) @map(\"trigger_timeout_ms\")\n\n  // ============ 行为配置 ============\n  /// 最大重试次数\n  maxRetries       Int     @default(3) @map(\"max_retries\")\n  /// 重试间隔（毫秒）\n  retryDelayMs     Int     @default(2000) @map(\"retry_delay_ms\")\n  /// 是否保持协议一致（降级时是否允许切换协议）\n  preserveProtocol Boolean @default(false) @map(\"preserve_protocol\")\n\n  // ============ 状态 ============\n  /// 是否启用\n  isActive  Boolean @default(true) @map(\"is_active\")\n  /// 是否为内置链\n  isBuiltin Boolean @default(false) @map(\"is_builtin\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  @@index([isActive])\n  @@index([isBuiltin])\n  @@index([isDeleted])\n  @@map(\"b_fallback_chain\")\n}\n\n/// CostStrategy - 成本策略配置\n/// 定义成本优化策略，用于模型选择决策\nmodel CostStrategy {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 策略标识（如 lowest-cost, best-value, performance-first, balanced）\n  strategyId  String  @unique @map(\"strategy_id\") @db.VarChar(50)\n  /// 显示名称\n  name        String  @db.VarChar(100)\n  /// 策略描述\n  description String? @db.Text\n\n  // ============ 优化权重（0-1，总和为 1）============\n  /// 成本权重\n  costWeight        Decimal @default(0.5) @map(\"cost_weight\") @db.Decimal(3, 2)\n  /// 性能权重\n  performanceWeight Decimal @default(0.3) @map(\"performance_weight\") @db.Decimal(3, 2)\n  /// 能力权重\n  capabilityWeight  Decimal @default(0.2) @map(\"capability_weight\") @db.Decimal(3, 2)\n\n  // ============ 约束条件 ============\n  /// 单次请求最大成本（美元）\n  maxCostPerRequest  Decimal? @map(\"max_cost_per_request\") @db.Decimal(10, 6)\n  /// 最大延迟（毫秒）\n  maxLatencyMs       Int?     @map(\"max_latency_ms\")\n  /// 最低能力评分\n  minCapabilityScore Int?     @map(\"min_capability_score\")\n\n  /// 场景权重配置（JSON）\n  /// { \"reasoning\": 0.5, \"coding\": 0.3, \"creativity\": 0.2, \"speed\": 0.5 }\n  scenarioWeights Json? @map(\"scenario_weights\") @db.JsonB\n\n  // ============ 状态 ============\n  /// 是否启用\n  isActive  Boolean @default(true) @map(\"is_active\")\n  /// 是否为内置策略\n  isBuiltin Boolean @default(false) @map(\"is_builtin\")\n\n  isDeleted Boolean   @default(false) @map(\"is_deleted\")\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime  @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  deletedAt DateTime? @map(\"deleted_at\") @db.Timestamptz(6)\n\n  @@index([isActive])\n  @@index([isBuiltin])\n  @@index([isDeleted])\n  @@map(\"b_cost_strategy\")\n}\n\n/// BotRoutingConfig - Bot 路由配置\n/// 存储 Bot 的智能路由、Fallback 和成本控制配置\nmodel BotRoutingConfig {\n  id    String @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  botId String @unique @map(\"bot_id\") @db.Uuid\n\n  // ============ 路由配置 ============\n  /// 是否启用智能路由\n  routingEnabled Boolean @default(true) @map(\"routing_enabled\")\n  /// 路由模式：auto | manual | cost-optimized\n  routingMode    String  @default(\"auto\") @map(\"routing_mode\") @db.VarChar(20)\n\n  // ============ Fallback 配置 ============\n  /// 是否启用 Fallback\n  fallbackEnabled Boolean @default(true) @map(\"fallback_enabled\")\n  /// 默认 Fallback 链 ID\n  fallbackChainId String? @map(\"fallback_chain_id\") @db.VarChar(50)\n\n  // ============ 成本控制配置 ============\n  /// 是否启用成本控制\n  costControlEnabled Boolean  @default(false) @map(\"cost_control_enabled\")\n  /// 成本策略 ID\n  costStrategyId     String?  @map(\"cost_strategy_id\") @db.VarChar(50)\n  /// 每日预算（美元）\n  dailyBudget        Decimal? @map(\"daily_budget\") @db.Decimal(10, 2)\n  /// 每月预算（美元）\n  monthlyBudget      Decimal? @map(\"monthly_budget\") @db.Decimal(10, 2)\n  /// 预算告警阈值（0-1）\n  alertThreshold     Decimal? @default(0.8) @map(\"alert_threshold\") @db.Decimal(3, 2)\n  /// 是否启用自动降级\n  autoDowngrade      Boolean  @default(false) @map(\"auto_downgrade\")\n  /// 降级目标模型\n  downgradeModel     String?  @map(\"downgrade_model\") @db.VarChar(100)\n\n  // ============ 复杂度路由配置 ============\n  /// 是否启用复杂度路由\n  complexityRoutingEnabled  Boolean @default(false) @map(\"complexity_routing_enabled\")\n  /// 复杂度路由配置 ID\n  complexityRoutingConfigId String? @map(\"complexity_routing_config_id\") @db.VarChar(50)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  bot Bot @relation(fields: [botId], references: [id], onDelete: Cascade)\n\n  @@index([botId])\n  @@index([routingEnabled])\n  @@index([costControlEnabled])\n  @@index([complexityRoutingEnabled])\n  @@map(\"b_bot_routing_config\")\n}\n\n/// ComplexityRoutingConfig - 复杂度路由配置\n/// 存储基于消息复杂度的模型路由配置\nmodel ComplexityRoutingConfig {\n  id          String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 配置唯一标识符\n  configId    String  @unique @map(\"config_id\") @db.VarChar(50)\n  /// 配置名称\n  name        String  @db.VarChar(100)\n  /// 配置描述\n  description String? @db.Text\n\n  // ============ 模型配置 ============\n  /// @deprecated 旧的 JSON 模型配置，迁移到 ComplexityRoutingModelMapping 关联表后移除\n  /// 格式: { super_easy: {vendor, model}, easy: {...}, medium: {...}, hard: {...}, super_hard: {...} }\n  models Json? @db.JsonB\n\n  // 新：通过关联表引用实际可用模型\n  modelMappings ComplexityRoutingModelMapping[]\n\n  // ============ 分类器配置 ============\n  /// 分类器使用的模型\n  classifierModel  String @default(\"deepseek-v3-250324\") @map(\"classifier_model\") @db.VarChar(100)\n  /// 分类器使用的 vendor\n  classifierVendor String @default(\"deepseek\") @map(\"classifier_vendor\") @db.VarChar(50)\n\n  // ============ 行为配置 ============\n  /// 工具调用时的最低复杂度\n  toolMinComplexity String? @map(\"tool_min_complexity\") @db.VarChar(20)\n\n  // ============ 状态 ============\n  /// 是否启用\n  isEnabled Boolean @default(true) @map(\"is_enabled\")\n  /// 是否为内置配置\n  isBuiltin Boolean @default(false) @map(\"is_builtin\")\n  /// 软删除标记\n  isDeleted Boolean @default(false) @map(\"is_deleted\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@index([configId])\n  @@index([isEnabled])\n  @@index([isDeleted])\n  @@map(\"b_complexity_routing_config\")\n}\n\n/// FallbackChainModel - Fallback 链模型关联表\n/// 引用 ModelCatalog（模型级别），运行时动态解析到可用 vendor\nmodel FallbackChainModel {\n  id               String  @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 关联的 FallbackChain ID\n  fallbackChainId  String  @map(\"fallback_chain_id\") @db.Uuid\n  /// 关联的 ModelCatalog ID（模型级别，运行时解析到可用 vendor）\n  modelCatalogId   String  @map(\"model_catalog_id\") @db.Uuid\n  /// 在链中的顺序（0 = 首选模型，数值越小优先级越高）\n  priority         Int     @default(0)\n  /// 协议覆盖（可选，默认使用 ProviderKey 的 apiType）\n  protocolOverride String? @map(\"protocol_override\") @db.VarChar(50)\n  /// 特性覆盖配置（JSON），如 { extendedThinking: true, cacheControl: true }\n  featuresOverride Json?   @map(\"features_override\") @db.JsonB\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  fallbackChain FallbackChain @relation(fields: [fallbackChainId], references: [id], onDelete: Cascade)\n  modelCatalog  ModelCatalog  @relation(fields: [modelCatalogId], references: [id], onDelete: Cascade)\n\n  @@unique([fallbackChainId, modelCatalogId])\n  @@index([fallbackChainId])\n  @@index([modelCatalogId])\n  @@index([priority])\n  @@map(\"b_fallback_chain_model\")\n}\n\n/// ComplexityRoutingModelMapping - 复杂度路由模型映射表\n/// 引用 ModelCatalog（模型级别），运行时动态解析到可用 vendor\nmodel ComplexityRoutingModelMapping {\n  id                 String @id @default(dbgenerated(\"uuid_generate_v4()\")) @db.Uuid\n  /// 关联的 ComplexityRoutingConfig ID\n  complexityConfigId String @map(\"complexity_config_id\") @db.Uuid\n  /// 复杂度级别：super_easy, easy, medium, hard, super_hard\n  complexityLevel    String @map(\"complexity_level\") @db.VarChar(20)\n  /// 关联的 ModelCatalog ID（模型级别）\n  modelCatalogId     String @map(\"model_catalog_id\") @db.Uuid\n  /// 在同级别中的优先级（0 = 首选）\n  priority           Int    @default(0)\n\n  createdAt DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  complexityConfig ComplexityRoutingConfig @relation(fields: [complexityConfigId], references: [id], onDelete: Cascade)\n  modelCatalog     ModelCatalog            @relation(fields: [modelCatalogId], references: [id], onDelete: Cascade)\n\n  @@unique([complexityConfigId, complexityLevel, modelCatalogId])\n  @@index([complexityConfigId])\n  @@index([modelCatalogId])\n  @@index([complexityLevel])\n  @@map(\"b_complexity_routing_model_mapping\")\n}\n"
}

